#include "i18n.h"
#include <cstring>
#include <deque>
#include <string_view>
#include <unordered_map>

namespace {
struct Catalog { const char* code; const char* text; };
#include "i18n_catalogs.inc"   // generated by CMake from app/i18n/*.txt: static const Catalog kCatalogs[] = {{"de", R"..."}, ...};

const i18n::Language kLanguages[] = {
    {"en", "English"}, {"de", "Deutsch"}, {"fr", "Fran\xC3\xA7" "ais"}, {"es", "Espa\xC3\xB1ol"},
    {"zh", "\xE4\xB8\xAD\xE6\x96\x87 (\xE7\xAE\x80\xE4\xBD\x93)"}, {"lt", "Lietuvi\xC5\xB3"}, {"hu", "Magyar"},
    {"ja", "\xE6\x97\xA5\xE6\x9C\xAC\xE8\xAA\x9E"}, {"pl", "Polski"}, {"nl", "Nederlands"},
    {"pt", "Portugu\xC3\xAA" "s (Brasil)"}, {"pt-PT", "Portugu\xC3\xAA" "s (Portugal)"}, {"it", "Italiano"}, {"ru", "\xD0\xA0\xD1\x83\xD1\x81\xD1\x81\xD0\xBA\xD0\xB8\xD0\xB9"},
};
constexpr int kNumLanguages = (int)(sizeof kLanguages / sizeof *kLanguages);

struct Loaded {
    std::deque<std::string> store;                                 // the texts, never moved
    std::unordered_map<std::string_view, const char*> map;         // English -> translation
    std::unordered_map<std::string, std::string> composed, ids;    // tr() of "Label##id", trw()
    bool empty = true;                                             // English: nothing to look up
};

std::string unescape(std::string_view s) {
    std::string o;
    o.reserve(s.size());
    for (size_t i = 0; i < s.size(); i++) {
        if (s[i] == '\\' && i + 1 < s.size()) {
            const char c = s[++i];
            o += c == 'n' ? '\n' : c == 't' ? '\t' : c;
        } else o += s[i];
    }
    return o;
}

void parse(Loaded& L, const char* text) {   // a later text for the same key wins
    std::string_view all(text);
    size_t pos = 0;
    while (pos < all.size()) {
        size_t end = all.find('\n', pos);
        if (end == std::string_view::npos) end = all.size();
        std::string_view line = all.substr(pos, end - pos);
        pos = end + 1;
        if (!line.empty() && line.back() == '\r') line.remove_suffix(1);
        if (line.empty() || line[0] == '#') continue;
        const size_t tab = line.find('\t');
        if (tab == std::string_view::npos || tab + 1 >= line.size()) continue;   // untranslated
        const std::string& k = L.store.emplace_back(unescape(line.substr(0, tab)));
        const std::string& v = L.store.emplace_back(unescape(line.substr(tab + 1)));
        L.map[std::string_view(k)] = v.c_str();
    }
}

Loaded& load(int idx) {
    static Loaded langs[kNumLanguages];
    static bool done[kNumLanguages] = {};
    Loaded& L = langs[idx];
    if (done[idx]) return L;
    done[idx] = true;
    const std::string code = kLanguages[idx].code;
    const size_t dash = code.find('-');
    if (dash != std::string::npos)   // a regional catalog (pt-PT) holds only the texts that differ from its base (pt)
        if (const char* base = i18n::catalogText(code.substr(0, dash).c_str())) parse(L, base);
    if (const char* text = i18n::catalogText(code.c_str())) parse(L, text);
    L.empty = L.map.empty();
    return L;
}

int gCur = 0;

const char* lookup(Loaded& L, std::string_view k) {
    auto it = L.map.find(k);
    return it == L.map.end() ? nullptr : it->second;
}
}

const char* i18n::catalogText(const char* code) {
    for (const Catalog& c : kCatalogs) if (std::strcmp(c.code, code) == 0) return c.text;
    return nullptr;
}

const i18n::Language* i18n::languages(int& count) { count = kNumLanguages; return kLanguages; }
const char* i18n::current() { return kLanguages[gCur].code; }

const char* i18n::set(const std::string& code) {
    std::string c, full;   // "pt" and "pt-pt" for "pt_PT.UTF-8"
    for (char ch : code) {
        if (ch == '.' || ch == '@') break;
        if (ch == '-' || ch == '_') { full += '-'; continue; }
        const char l = (char)(ch >= 'A' && ch <= 'Z' ? ch - 'A' + 'a' : ch);
        if (full.size() == c.size()) c += l;
        full += l;
    }
    auto lower = [](const char* s) { std::string o; for (; *s; s++) o += (char)(*s >= 'A' && *s <= 'Z' ? *s - 'A' + 'a' : *s); return o; };
    gCur = 0;
    for (int i = 0; i < kNumLanguages; i++) if (c == kLanguages[i].code) gCur = i;
    for (int i = 0; i < kNumLanguages; i++) if (full != c && full == lower(kLanguages[i].code)) gCur = i;   // a listed region (pt-PT) wins over its base
    load(gCur);
    return kLanguages[gCur].code;
}

const char* tr(const char* s) {
    if (!s || gCur == 0) return s;
    Loaded& L = load(gCur);
    if (L.empty || !*s) return s;
    const std::string_view sv(s);
    if (const char* t = lookup(L, sv)) return t;
    const size_t hh = sv.find("##");
    if (hh == std::string_view::npos || hh == 0) return s;
    auto c = L.composed.find(std::string(sv));
    if (c != L.composed.end()) return c->second.c_str();
    const char* t = lookup(L, sv.substr(0, hh));
    std::string& out = L.composed[std::string(sv)];
    out = t ? std::string(t) + std::string(sv.substr(hh)) : std::string(sv);
    return out.c_str();
}

const char* trw(const char* s) {
    if (!s) return s;
    Loaded& L = load(gCur);
    const std::string key(s);
    auto it = L.ids.find(key);
    if (it != L.ids.end()) return it->second.c_str();
    const size_t hh = key.find("##"), hhh = key.find("###");
    const std::string vis = key.substr(0, hh);
    const char* t = vis.empty() ? "" : gCur ? lookup(L, vis) : nullptr;
    std::string& out = L.ids[key];
    out = std::string(t ? t : vis.c_str()) + (hhh != std::string::npos ? key.substr(hhh) : "###" + key);
    return out.c_str();
}
